/**
 * Model User
 * Platform user — both customers and administrators.
 * Roles are controlled server-side only; clients cannot self-elevate.
 */
export type User = $Result.DefaultSelection<Prisma.$UserPayload>
/**
 * Model Account
 * OAuth / credential accounts linked to a User (Auth.js requirement).
 */
export type Account = $Result.DefaultSelection<Prisma.$AccountPayload>
/**
 * Model Session
 * Database sessions (Auth.js requirement when using database sessions).
 */
export type Session = $Result.DefaultSelection<Prisma.$SessionPayload>
/**
 * Model VerificationToken
 * Email-verification and password-reset tokens (Auth.js requirement).
 */
export type VerificationToken = $Result.DefaultSelection<Prisma.$VerificationTokenPayload>
/**
 * Model CustomerProfile
 * Extended profile information for customers.
 * Kept separate from User so auth models stay clean.
 */
export type CustomerProfile = $Result.DefaultSelection<Prisma.$CustomerProfilePayload>
/**
 * Model TemplateCategory
 * Occasion categories for filtering templates.
 */
export type TemplateCategory = $Result.DefaultSelection<Prisma.$TemplateCategoryPayload>
/**
 * Model Template
 * A reusable invitation template design.
 * Design configuration is stored as JSON; the application layer validates it.
 */
export type Template = $Result.DefaultSelection<Prisma.$TemplatePayload>
/**
 * Model TemplateVersion
 * Immutable version snapshot of a template design.
 * Existing invitations pin to a specific version so layout updates do not break them.
 */
export type TemplateVersion = $Result.DefaultSelection<Prisma.$TemplateVersionPayload>
/**
 * Model Invitation
 * One customer's live invitation instance, tied to a template version.
 * Tracks separate lifecycle states from draft → published.
 */
export type Invitation = $Result.DefaultSelection<Prisma.$InvitationPayload>
/**
 * Model EventData
 * The event information attached to an invitation.
 * Stored as a separate record for clean separation of data vs. design.
 */
export type EventData = $Result.DefaultSelection<Prisma.$EventDataPayload>
/**
 * Model InvitationImage
 * Guest-uploaded or admin-uploaded images for an invitation.
 */
export type InvitationImage = $Result.DefaultSelection<Prisma.$InvitationImagePayload>
/**
 * Model RSVPConfig
 * Host-configurable RSVP settings per invitation.
 */
export type RSVPConfig = $Result.DefaultSelection<Prisma.$RSVPConfigPayload>
/**
 * Model RSVP
 * A guest's RSVP submission for a published invitation.
 */
export type RSVP = $Result.DefaultSelection<Prisma.$RSVPPayload>
/**
 * Model Inquiry
 * Customer inquiry submitted through the custom invitation form.
 * First step of the custom-service workflow.
 */
export type Inquiry = $Result.DefaultSelection<Prisma.$InquiryPayload>
/**
 * Model Order
 * An order links a customer, invitation, and payment lifecycle together.
 * Supports both self-service (template purchase) and custom-service workflows.
 */
export type Order = $Result.DefaultSelection<Prisma.$OrderPayload>
/**
 * Model SeatingTable
 * Tables created for an order / invitation to seat confirmed guests
 */
export type SeatingTable = $Result.DefaultSelection<Prisma.$SeatingTablePayload>
/**
 * Model SeatingAssignment
 * Assignment of a guest / RSVP to a table
 */
export type SeatingAssignment = $Result.DefaultSelection<Prisma.$SeatingAssignmentPayload>
/**
 * Model Quotation
 * A price quotation presented to the customer for approval.
 */
export type Quotation = $Result.DefaultSelection<Prisma.$QuotationPayload>
/**
 * Model PaymentRecord
 * Payment record — never stores raw card data.
 * Records payment reference, timestamps, and provider-confirmed status.
 */
export type PaymentRecord = $Result.DefaultSelection<Prisma.$PaymentRecordPayload>
/**
 * Model RevisionRequest
 * Customer-initiated revision request for a custom-service order.
 */
export type RevisionRequest = $Result.DefaultSelection<Prisma.$RevisionRequestPayload>
/**
 * Model OrderStatusLog
 * Append-only audit trail for important order status transitions.
 */
export type OrderStatusLog = $Result.DefaultSelection<Prisma.$OrderStatusLogPayload>
/**
 * Model BusinessSetting
 * Key-value store for editable business settings (packages, pricing, policies).
 * Values are stored as JSON strings to support rich configuration.
 */
export type BusinessSetting = $Result.DefaultSelection<Prisma.$BusinessSettingPayload>
/**
 * Model AuditLog
 * Append-only log of important administrative actions.
 */
export type AuditLog = $Result.DefaultSelection<Prisma.$AuditLogPayload>

